const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 300)); }
const items = []; const skip = []; let total = 0; let descs = 0;
for (const k of b.keys) {
  const spec = cfg.P[String(k.key_id)]; if (!spec) { continue; }
  const m = {}, by = {}, mt = {};
  for (const t of (k.translations || [])) { m[t.language_iso] = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); by[t.language_iso] = String(t.modified_by_email || '').toLowerCase(); mt[t.language_iso] = t.modified_at; }
  if (k.is_archived || k.is_plural) { skip.push([k.key_id, 'archived/plural']); continue; }
  if (mt.en !== TS) { skip.push([k.key_id, 'EN changed since read']); continue; }
  const item = { key_id: k.key_id };
  const dd = cfg.D[String(k.key_id)];
  if (dd) { if (k.description === dd.new) { skip.push([k.key_id, 'description already']); } else if (k.description !== dd.old) { skip.push([k.key_id, 'description changed since read']); } else { item.description = dd.new; descs++; } }
  const tr = [];
  for (const iso in spec) {
    total++;
    const newv = spec[iso];
    const live = m[iso] || '';
    if (live === newv) { skip.push([k.key_id, iso, 'already']); continue; }
    if (mt[iso] !== TS) { skip.push([k.key_id, iso, 'target changed since read']); continue; }
    if (LING.indexOf(by[iso]) !== -1) { skip.push([k.key_id, iso, 'linguist edit: ' + by[iso]]); continue; }
    tr.push({ language_iso: iso, translation: newv, is_unverified: true });
  }
  if (tr.length) { item.translations = tr; }
  if (tr.length || item.description) { items.push(item); }
}
let sel = items;
if (MODE === 'test') { sel = items.filter(function (x) { return String(x.key_id) === '968559222'; }).slice(0, 1); if (sel.length) { sel = [{ key_id: sel[0].key_id, translations: sel[0].translations.filter(function (t) { return t.language_iso === 'de'; }) }]; } }
const reqs = [];
for (let i = 0; i < sel.length; i += 6) { const part = sel.slice(i, i + 6); reqs.push({ body: JSON.stringify({ keys: part }) }); }
const cnt = function (arr) { return arr.reduce(function (a, x) { return a + (x.translations ? x.translations.length : 0); }, 0); };
return [{ json: { mode: MODE, keys_expected: Object.keys(cfg.P).length, keys_found: b.keys.length, slots: total, ready: cnt(items), descriptions: descs, to_write: cnt(sel), skipped: skip.length, skip_list: skip, requests: reqs } }];

const cfg = $('Config').first().json;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { return [{ json: { error: 'read-back failed', body: JSON.stringify(b).slice(0, 300) } }]; }
let match = 0; const diff = []; const desc = [];
for (const k of b.keys) {
  const spec = cfg.P[String(k.key_id)]; if (!spec) { continue; }
  const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = t.translation; }
  for (const iso in spec) { const v = m[iso]; if (v === spec[iso]) { match++; } else { diff.push([k.key_id, iso, String(v).slice(0, 120)]); } }
  const dd = cfg.D[String(k.key_id)]; if (dd) { desc.push([k.key_id, k.description === dd.new ? 'new' : 'NOT updated']); }
}
let res = [];
try { res = $('WRITE translations').all().map(function (x) { return { status: x.json.statusCode, written: ((x.json.body || {}).keys || []).length, errors: (x.json.body || {}).errors || null }; }); } catch (e) { res = ['no write this run']; }
return [{ json: { write_results: res, readback: { match: match, different: diff.length, diff_sample: diff.slice(0, 15), description: desc } } }];
